<template>
  <div class="page-ai-heal">
    <h2 class="page-title">{{ t('ai.heal.title') }}</h2>

    <el-card>
      <el-form
        v-if="config"
        ref="formRef"
        :model="form"
        :rules="rules"
        label-width="160px"
      >
        <el-form-item :label="t('ai.heal.enableAnalysis')">
          <el-switch v-model="form.enabled" />
        </el-form-item>

        <el-form-item :label="t('ai.heal.provider')" prop="provider">
          <el-select v-model="form.provider" :disabled="!form.enabled">
            <el-option label="OpenAI" value="openai" />
            <el-option label="Anthropic" value="anthropic" />
            <el-option label="Ollama" value="ollama" />
          </el-select>
        </el-form-item>

        <el-form-item :label="t('ai.heal.model')" prop="model">
          <el-input v-model="form.model" :disabled="!form.enabled" placeholder="gpt-4o-mini" />
        </el-form-item>

        <el-form-item label="API Key" prop="api_key">
          <el-input
            v-model="form.api_key"
            type="password"
            show-password
            :disabled="!form.enabled || form.provider === 'ollama'"
            :placeholder="t('ai.heal.apiKeyPlaceholder')"
          />
        </el-form-item>

        <el-form-item label="API Base URL">
          <el-input
            v-model="form.api_base"
            :disabled="!form.enabled"
            :placeholder="t('ai.heal.apiBasePlaceholder')"
          />
        </el-form-item>

        <el-form-item :label="t('ai.heal.autoExecuteWhitelist')">
          <el-switch v-model="form.auto_execute" :disabled="!form.enabled" />
          <div class="form-hint">
            {{ t('ai.heal.autoExecuteHint') }}
          </div>
        </el-form-item>

        <el-form-item :label="t('ai.heal.snapshotBeforeExec')">
          <el-switch v-model="form.snapshot_enabled" :disabled="!form.enabled" />
        </el-form-item>

        <el-form-item :label="t('ai.heal.snapshotKeepCount')" prop="snapshot_keep_count">
          <el-input-number
            v-model="form.snapshot_keep_count"
            :min="0"
            :max="10"
            :disabled="!form.enabled"
          />
        </el-form-item>

        <el-form-item :label="t('ai.heal.maxContextLines')" prop="max_context_lines">
          <el-input-number
            v-model="form.max_context_lines"
            :min="10"
            :max="500"
            :disabled="!form.enabled"
          />
          <div class="form-hint">{{ t('ai.heal.maxContextLinesHint') }}</div>
        </el-form-item>

        <el-form-item :label="t('ai.heal.autoAnalyze')">
          <el-switch v-model="form.auto_analyze" :disabled="!form.enabled" />
          <div class="form-hint">{{ t('ai.heal.autoAnalyzeHint') }}</div>
        </el-form-item>

        <el-form-item :label="t('ai.heal.rateMode')">
          <el-select v-model="form.rate_mode" :disabled="!form.enabled">
            <el-option :label="t('ai.heal.rateModeAdaptive')" value="adaptive" />
            <el-option :label="t('ai.heal.rateModeFixed')" value="fixed" />
          </el-select>
        </el-form-item>

        <el-form-item v-if="form.rate_mode === 'fixed'" :label="t('ai.heal.fixedRate')">
          <el-input-number
            v-model="form.fixed_rate"
            :min="1"
            :max="60"
            :disabled="!form.enabled"
          />
          <div class="form-hint">{{ t('ai.heal.fixedRateHint') }}</div>
        </el-form-item>

        <el-form-item v-else :label="t('ai.heal.maxRate')">
          <el-input-number
            v-model="form.max_rate"
            :min="1"
            :max="60"
            :disabled="!form.enabled"
          />
          <div class="form-hint">{{ t('ai.heal.maxRateHint') }}</div>
        </el-form-item>

        <el-form-item>
          <el-button type="primary" :loading="saving" @click="onSave">
            {{ t('ai.heal.saveConfig') }}
          </el-button>
        </el-form-item>
      </el-form>

      <el-skeleton v-else :rows="8" animated />
    </el-card>

    <el-card v-if="rateStatus" class="hint-card">
      <template #header>
        <span>{{ t('ai.heal.rateStatusTitle') }}</span>
      </template>
      <el-descriptions :column="2" border>
        <el-descriptions-item :label="t('ai.heal.rateMode')">
          {{ rateStatus.mode === 'adaptive' ? t('ai.heal.rateModeAdaptive') : t('ai.heal.rateModeFixed') }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('ai.heal.currentRate')">
          {{ rateStatus.effective_rate }} {{ t('ai.heal.perMinute') }}
        </el-descriptions-item>
        <el-descriptions-item
          v-if="rateStatus.mode === 'adaptive'"
          :label="t('ai.heal.adaptiveRate')"
        >
          {{ rateStatus.adaptive_rate }} {{ t('ai.heal.perMinute') }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('ai.heal.recentAvgDuration')">
          {{
            rateStatus.avg_duration_ms !== null
              ? (rateStatus.avg_duration_ms / 1000).toFixed(1) + 's'
              : '-'
          }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('ai.heal.startsLastMinute')">
          {{ rateStatus.starts_last_minute }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('ai.heal.measurementCount')">
          {{ rateStatus.measurement_count }}
        </el-descriptions-item>
      </el-descriptions>
    </el-card>

    <el-card class="hint-card">
      <template #header>
        <span>{{ t('ai.heal.usageTitle') }}</span>
      </template>
      <ul>
        <li>{{ t('ai.heal.usage1') }}</li>
        <li>{{ t('ai.heal.usage2') }}</li>
        <li>{{ t('ai.heal.usage3') }}</li>
        <li>{{ t('ai.heal.usage4') }}</li>
      </ul>
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { reactive, ref, onMounted } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import {
  getAIConfig,
  getAIRateStatus,
  updateAIConfig,
  type AIConfigRead,
  type AIConfigUpdate,
  type AIRateStatus,
} from '@/api/ai'
import { showError } from '@/utils/error'

const { t } = useI18n()

const config = ref<AIConfigRead | null>(null)
const rateStatus = ref<AIRateStatus | null>(null)
const loading = ref(false)
const saving = ref(false)
const formRef = ref<FormInstance>()

const form = reactive({
  enabled: false,
  provider: 'openai',
  model: 'gpt-4o-mini',
  api_key: '',
  api_base: '',
  auto_execute: false,
  snapshot_enabled: true,
  snapshot_keep_count: 1,
  max_context_lines: 100,
  auto_analyze: true,
  rate_mode: 'adaptive',
  fixed_rate: 2,
  max_rate: 10,
})

const rules: FormRules = {
  provider: [{ required: true, message: () => t('ai.heal.providerRequired'), trigger: 'change' }],
  model: [{ required: true, message: () => t('ai.heal.modelRequired'), trigger: 'blur' }],
}

async function loadConfig() {
  loading.value = true
  try {
    const data = await getAIConfig()
    config.value = data
    form.enabled = data.enabled
    form.provider = data.provider
    form.model = data.model
    form.api_key = data.api_key || ''
    form.api_base = data.api_base || ''
    form.auto_execute = data.auto_execute
    form.snapshot_enabled = data.snapshot_enabled
    form.snapshot_keep_count = data.snapshot_keep_count
    form.max_context_lines = data.max_context_lines
    form.auto_analyze = data.auto_analyze
    form.rate_mode = data.rate_mode
    form.fixed_rate = data.fixed_rate
    form.max_rate = data.max_rate
  } catch (error) {
    showError(error, t('ai.heal.loadFailed'))
  } finally {
    loading.value = false
  }
}

async function loadRateStatus() {
  try {
    rateStatus.value = await getAIRateStatus()
  } catch {
    // 静默降级：限流状态加载失败不阻断配置页使用（零 console error）
    rateStatus.value = null
  }
}

async function onSave() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  saving.value = true
  try {
    const data: AIConfigUpdate = {
      enabled: form.enabled,
      provider: form.provider,
      model: form.model,
      api_key: form.api_key || undefined,
      api_base: form.api_base || undefined,
      auto_execute: form.auto_execute,
      snapshot_enabled: form.snapshot_enabled,
      snapshot_keep_count: form.snapshot_keep_count,
      max_context_lines: form.max_context_lines,
      auto_analyze: form.auto_analyze,
      rate_mode: form.rate_mode,
      fixed_rate: form.fixed_rate,
      max_rate: form.max_rate,
    }
    await updateAIConfig(data)
    ElMessage.success(t('ai.heal.saved'))
    loadConfig()
    loadRateStatus()
  } catch (error) {
    showError(error, t('ai.heal.saveFailed'))
  } finally {
    saving.value = false
  }
}

onMounted(() => {
  loadConfig()
  loadRateStatus()
})
</script>

<style scoped>
.page-ai-heal {
  padding: 20px;
}

.page-title {
  margin: 0 0 20px;
  font-size: 20px;
}

.form-hint {
  color: var(--el-text-color-secondary);
  font-size: 12px;
  margin-top: 4px;
}

.hint-card {
  margin-top: 20px;
}
</style>
